140: func sourceGuards(r Release) ([]*heldFile,error) {
141:     expected:=map[string]RawPin{}; var guards []*heldFile
142:     fail:=func(e error) ([]*heldFile,error) { for _,f:=range guards { f.file.Close() }; return nil,e }
143:     for _,p:=range r.SourceFiles {
144:         rel,e:=filepath.Rel(r.SourceRoot,p.Path); if e!=nil || !filepath.IsLocal(rel) { return fail(errors.New("AUTHORITY_SOURCE_SCOPE")) }
145:         key:=strings.ToLower(filepath.ToSlash(rel)); if _,ok:=expected[key]; ok { return fail(errors.New("AUTHORITY_SOURCE_DUPLICATE")) }; expected[key]=p
146:         f,_,e:=pinHeld(p); if e!=nil { return fail(e) }; guards=append(guards,f)
147:     }
148:     // Conservative repository-local coverage: every regular file under these
149:     // fixed product trees is required, regardless of suffix, dot/underscore
150:     // name, test status or go:embed directory/glob selection. Go embeds cannot
151:     // escape their package tree. Do not confuse this with a compiler-derived
152:     // closure of external modules: Root must separately verify go list -deps
153:     // EmbedFiles/compiled inputs against its accepted, pinned build inventory.
154:     dirs:=[]string{"apps/control","internal","adapters","evaluation","ops","migrations/sqlite","spec/v2.0/contracts"}
155:     if _,e:=os.Lstat(filepath.Join(r.SourceRoot,"vendor")); e==nil {
156:         dirs=append(dirs,"vendor")
157:     } else if !errors.Is(e,os.ErrNotExist) { return fail(e) }
158:     for _,dir:=range dirs {
159:         e:=filepath.WalkDir(filepath.Join(r.SourceRoot,filepath.FromSlash(dir)),func(path string,d os.DirEntry,e error) error {
160:             if e!=nil { return e }; if d.Type()&os.ModeSymlink!=0 { return errors.New("AUTHORITY_SOURCE_LINK") }; if d.IsDir() { return plainPath(path) }
161:             if !d.Type().IsRegular() { return errors.New("AUTHORITY_SOURCE_NONREGULAR") }
162:             rel,e:=filepath.Rel(r.SourceRoot,path); if e!=nil { return e }; if _,ok:=expected[strings.ToLower(filepath.ToSlash(rel))]; !ok { return fmt.Errorf("AUTHORITY_SOURCE_OMITTED:%s",filepath.ToSlash(rel)) }; return nil
163:         }); if e!=nil { return fail(e) }
164:     }
165:     for _,rel:=range []string{"go.mod","go.sum","execution/toolchains/locked.json"} { if _,ok:=expected[rel]; !ok { return fail(errors.New("AUTHORITY_REQUIRED_BUILD_PIN")) } }
166:     // The accepted build still uses GOWORK=off; pin any present workspace files
167:     // conservatively so an unexpected local build selector cannot be omitted.
168:     for _,rel:=range []string{"go.work","go.work.sum"} {
169:         if _,e:=os.Lstat(filepath.Join(r.SourceRoot,rel)); e==nil {
170:             if _,ok:=expected[rel]; !ok { return fail(fmt.Errorf("AUTHORITY_REQUIRED_BUILD_PIN:%s",rel)) }
171:         } else if !errors.Is(e,os.ErrNotExist) { return fail(e) }
172:     }
173:     return guards,nil
