85: func requireSourceInventoryOmission(t *testing.T,release Release,rel string) {
86:     t.Helper()
87:     expectedPath:=filepath.Join(release.SourceRoot,filepath.FromSlash(rel))
88:     filtered:=[]RawPin{}; found:=false
89:     for _,p:=range release.SourceFiles { if p.Path==expectedPath { found=true } else { filtered=append(filtered,p) } }
90:     if !found { t.Fatal("test did not remove a real declared member") }
91:     release.SourceFiles=filtered
92:     guards,err:=sourceGuards(release)
93:     for _,g:=range guards { _=g.file.Close() }
94:     if err==nil || err.Error()!="AUTHORITY_SOURCE_OMITTED:"+rel { t.Fatalf("omitting %s: got %v",rel,err) }
95:     // A failed inventory must release earlier handles, including the remaining
96:     // actual embedded JSON file, so rejection cannot leak a permanent read lock.
97:     for _,p:=range release.SourceFiles { if strings.HasSuffix(p.Path,"new-project-rules-v24.json") { if err=os.WriteFile(p.Path,[]byte("released after reject"),0600); err!=nil { t.Fatal(err) }; break } }
98: }
